package hasher

import (
	"crypto/rand"
	"encoding/binary"
	"hash/maphash"
	"sync"
)

var instance = NewHasher()

func Reseed(id string) {
	instance.Reseed(id)
}

func SetSeed(id, seed string) {
	instance.SetSeed(id, seed)
}

func HashFunc() func(id, str string) uint64 {
	return instance.HashFunc()
}

// Hasher maintains a seed for each identifier and a hash seed shared by its hashes.
type Hasher struct {
	mu       sync.Mutex
	seeds    map[string]string
	hashSeed maphash.Seed
}

func NewHasher() *Hasher {
	return &Hasher{
		seeds:    make(map[string]string),
		hashSeed: maphash.MakeSeed(),
	}
}

// SetSeed assigns a reproducible seed to the given id.
func (h *Hasher) SetSeed(id, seed string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.seeds[id] = seed
}

// Reseed generates a new seed for the given id.
func (h *Hasher) Reseed(id string) {
	h.mu.Lock()
	defer h.mu.Unlock()
	h.seeds[id] = randomSeed()
}

func randomSeed() string {
	var seed [16]byte
	if _, err := rand.Read(seed[:]); err != nil {
		panic(err)
	}
	return string(seed[:])
}

// HashFunc returns a function that hashes a string using the seed for the given id.
func (h *Hasher) HashFunc() func(id, str string) uint64 {
	return func(id, str string) uint64 {
		h.mu.Lock()
		seed, ok := h.seeds[id]
		if !ok {
			seed = randomSeed()
			h.seeds[id] = seed
		}
		h.mu.Unlock()

		var hash maphash.Hash
		hash.SetSeed(h.hashSeed)
		var length [8]byte
		binary.LittleEndian.PutUint64(length[:], uint64(len(seed)))
		_, _ = hash.Write(length[:])
		_, _ = hash.WriteString(seed)
		_, _ = hash.WriteString(str)
		return hash.Sum64()
	}
}
package hasher_test

import (
	"testing"

	"github.com/navidrome/navidrome/utils/hasher"
	. "github.com/onsi/ginkgo/v2"
	. "github.com/onsi/gomega"
)

func TestHasher(t *testing.T) {
	RegisterFailHandler(Fail)
	RunSpecs(t, "Hasher Suite")
}

var _ = Describe("HashFunc", func() {
	const input = "123e4567e89b12d3a456426614174000"

	It("uses a specified seed and restores the same hash after reseeding", func() {
		h := hasher.NewHasher()
		hashFunc := h.HashFunc()
		h.SetSeed("id", "original")
		original := hashFunc("id", input)
		Expect(hashFunc("id", input)).To(Equal(original))

		h.SetSeed("id", "another")
		Expect(hashFunc("id", input)).NotTo(Equal(original))
		h.Reseed("id")
		Expect(hashFunc("id", input)).NotTo(Equal(original))

		h.SetSeed("id", "original")
		Expect(hashFunc("id", input)).To(Equal(original))
	})

	It("supports setting a seed on the package hasher", func() {
		const id = "package-seed-test"
		hashFunc := hasher.HashFunc()
		hasher.SetSeed(id, "first")
		first := hashFunc(id, input)
		hasher.SetSeed(id, "second")
		Expect(hashFunc(id, input)).NotTo(Equal(first))
		hasher.SetSeed(id, "first")
		Expect(hashFunc(id, input)).To(Equal(first))
	})

	It("initializes an unset id and retains its hash", func() {
		hashFunc := hasher.NewHasher().HashFunc()
		first := hashFunc("unset", input)
		Expect(hashFunc("unset", input)).To(Equal(first))
	})

	It("hashes the input and returns the sum", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		Expect(sum > 0).To(BeTrue())
	})

	It("hashes the input, reseeds and returns a different sum", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		hasher.Reseed("1")
		sum2 := hashFunc("1", input)
		Expect(sum).NotTo(Equal(sum2))
	})

	It("keeps different hashes for different ids", func() {
		hashFunc := hasher.HashFunc()
		sum := hashFunc("1", input)
		sum2 := hashFunc("2", input)

		Expect(sum).NotTo(Equal(sum2))

		Expect(sum).To(Equal(hashFunc("1", input)))
		Expect(sum2).To(Equal(hashFunc("2", input)))
	})
})

